class InvoiceItem{final int? id;final String description;final double quantity;final double rate;const InvoiceItem({this.id,required this.description,required this.quantity,required this.rate});double get amount=>quantity*rate;Map<String,dynamic> toMap(int invoiceId)=>{'id':id,'invoice_id':invoiceId,'description':description,'quantity':quantity,'rate':rate};factory InvoiceItem.fromMap(Map<String,dynamic> m)=>InvoiceItem(id:m['id'] as int?,description:m['description'] as String,quantity:(m['quantity'] as num).toDouble(),rate:(m['rate'] as num).toDouble());}
class Invoice{final int? id;final String invoiceNumber,customerName,customerAddress;final DateTime date;final double gstRate;final List<InvoiceItem> items;const Invoice({this.id,required this.invoiceNumber,required this.customerName,required this.customerAddress,required this.date,required this.gstRate,required this.items});double get subtotal=>items.fold(0,(s,i)=>s+i.amount);double get gstAmount=>subtotal*gstRate/100;double get total=>subtotal+gstAmount;Map<String,dynamic> toMap()=>{'id':id,'invoice_number':invoiceNumber,'customer_name':customerName,'customer_address':customerAddress,'date':date.toIso8601String(),'gst_rate':gstRate};factory Invoice.fromMap(Map<String,dynamic> m,List<InvoiceItem> items)=>Invoice(id:m['id'] as int?,invoiceNumber:m['invoice_number'] as String,customerName:m['customer_name'] as String,customerAddress:m['customer_address'] as String? ?? '',date:DateTime.parse(m['date'] as String),gstRate:(m['gst_rate'] as num).toDouble(),items:items);}
